23	/// A worker that manages the individual tools for a specific workspace
24	/// and reports back the results to the [`Backend`](crate::backend::Backend).
25	///
26	/// Each worker is responsible for a specific root URI and configures the tools `cwd` to that root URI.
27	/// The [`Backend`](crate::backend::Backend) is responsible to target the correct worker for a given file URI.
28	pub struct WorkspaceWorker {
29	    root_uri: Uri,
30	    tools: RwLock<Vec<Box<dyn Tool>>>,
31	    builders: Arc<[Box<dyn ToolBuilder>]>,
32	    // Initialized options from the client
33	    // If None, the worker has not been initialized yet
34	    pub(crate) options: Mutex<Option<serde_json::Value>>,
35	
36	    // Whether the client is in diagnostic pull mode / push mode, or not supporting diagnostics at all
37	    diagnostic_mode: DiagnosticMode,
38	    // Keep track of published diagnostics to clear them on shutdown (only in push mode)
39	    published_diagnostics: Mutex<FxHashSet<Uri>>,
40	}
41	
42	impl WorkspaceWorker {
43	    /// Create a new workspace worker.
44	    /// This will not start any programs, use [`start_worker`](Self::start_worker) for that.
45	    /// Depending on the client, we need to request the workspace configuration in `initialized` request.
46	    pub fn new(
47	        root_uri: Uri,
48	        builders: Arc<[Box<dyn ToolBuilder>]>,
49	        diagnostic_mode: DiagnosticMode,
50	    ) -> Self {
51	        Self {
52	            root_uri,
53	            tools: RwLock::new(vec![]),
54	            builders,
55	            options: Mutex::new(None),
56	            diagnostic_mode,
57	            published_diagnostics: Mutex::new(FxHashSet::default()),
58	        }
59	    }
60	
61	    /// Get the root URI of the worker
62	    pub fn get_root_uri(&self) -> &Uri {
63	        &self.root_uri
64	    }
65	
66	    /// Start all programs (linter, formatter) for the worker.
67	    /// This should be called after the client has sent the workspace configuration.
68	    pub async fn start_worker(&self, options: serde_json::Value) {
69	        *self.tools.write().await = self
70	            .builders
71	            .iter()
72	            .map(|builder| builder.build_boxed(&self.root_uri, options.clone()))
73	            .collect();
74	
75	        *self.options.lock().await = Some(options);
76	    }
77	
78	    /// Initialize file system watchers for the workspace.
79	    /// These watchers are used to watch for changes in the lint configuration files.
80	    /// The returned watchers will be registered to the client.
81	    pub async fn init_watchers(&self) -> Vec<Registration> {
82	        // clone the options to avoid locking the mutex
83	        let options_json = { self.options.lock().await.clone().unwrap_or_default() };
84	
85	        self.tools
86	            .read()
87	            .await
88	            .iter()
89	            .filter_map(|tool| {
90	                let patterns = tool.get_watcher_patterns(options_json.clone());
91	                if patterns.is_empty() {
92	                    None
93	                } else {
94	                    Some(registration_tool_watcher_id(tool.name(), &self.root_uri, patterns))
95	                }
96	            })
97	            .collect()
98	    }
99	
100	    /// Check if the worker needs to be initialized with options
101	    pub async fn needs_init_options(&self) -> bool {
102	        self.options.lock().await.is_none()
103	    }
104	
105	    /// Remove all internal cache for the given URI, if any.
106	    pub async fn remove_uri_cache(&self, uri: &Uri) {
107	        self.tools.read().await.iter().for_each(|tool| {
108	            tool.remove_uri_cache(uri);
109	        });
110	    }
111	
112	    /// Common aggregator for tool-provided diagnostics.
113	    async fn collect_diagnostics_with<F>(
114	        &self,
115	        uri: &Uri,
116	        content: Option<&str>,
117	        run: F,
118	    ) -> Result<Vec<(Uri, Vec<Diagnostic>)>, String>
119	    where
120	        F: Fn(&Box<dyn Tool>, &Uri, Option<&str>) -> DiagnosticResult,
121	    {
122	        let mut aggregated: FxHashMap<Uri, Vec<Diagnostic>> = FxHashMap::default();
123	
124	        for tool in self.tools.read().await.iter() {
125	            let tool_diagnostics = run(tool, uri, content);
126	
127	            match tool_diagnostics {
128	                Ok(diags) => {
129	                    for (entry_uri, mut diags) in diags {
130	                        aggregated.entry(entry_uri).or_default().append(&mut diags);
131	                    }
132	                }
133	                Err(err) => {
134	                    return Err(err);
135	                }
136	            }
137	        }
138	
139	        // In push mode, keep track of published diagnostics to clear them on shutdown
140	        if self.diagnostic_mode == DiagnosticMode::Push {
141	            let new_published_uris: FxHashSet<Uri> = aggregated.keys().cloned().collect();
142	            self.published_diagnostics.lock().await.extend(new_published_uris);
143	        }
144	
145	        let mut result = Vec::with_capacity(aggregated.len());
146	        for (uri, diags) in aggregated {
147	            result.push((uri, diags));
148	        }
149	        Ok(result)
150	    }
151	
152	    /// Run different tools to collect diagnostics.
153	    pub async fn run_diagnostic(
154	        &self,
155	        uri: &Uri,
156	        content: Option<&str>,
157	    ) -> Result<Vec<(Uri, Vec<Diagnostic>)>, String> {
158	        self.collect_diagnostics_with(uri, content, |tool, uri, content| {
159	            tool.run_diagnostic(uri, content)
160	        })
161	        .await
162	    }
163	
164	    /// Run different tools to collect diagnostics on change.
165	    pub async fn run_diagnostic_on_change(
166	        &self,
167	        uri: &Uri,
168	        content: Option<&str>,
169	    ) -> Result<Vec<(Uri, Vec<Diagnostic>)>, String> {
170	        self.collect_diagnostics_with(uri, content, |tool, uri, content| {
